// The constructor keeps public named params (`remoteDataSource`,
// `entriesBox`) distinct from the private fields they initialize, matching
// `account_settings_repository_impl.dart`'s documented convention.
// ignore_for_file: prefer_initializing_formals
import 'package:fpdart/fpdart.dart';
import 'package:hive_ce/hive_ce.dart';

import '../../../../core/failure/failure.dart';
import '../../../../core/utils/deduped_by_id.dart';
import '../../domain/entities/entries_page.dart';
import '../../domain/entities/entry.dart';
import '../../domain/repositories/entries_repository.dart';
import '../datasources/entries_remote_data_source.dart';
import '../models/entry_dto.dart';

/// On success, writes the entry through to the `entries` Hive box (`Box
/// <Map>`, keyed by id, raw `EntryDto.toJson()` — Design Notes) *before*
/// returning `right(...)`, same "persist then return" ordering
/// `AuthRepositoryImpl._authenticate` already uses for its own
/// post-success side effect.
class EntriesRepositoryImpl implements EntriesRepository {
  EntriesRepositoryImpl({
    required EntriesRemoteDataSource remoteDataSource,
    required Box<Map> entriesBox,
  }) : _remoteDataSource = remoteDataSource,
       _entriesBox = entriesBox;

  final EntriesRemoteDataSource _remoteDataSource;
  final Box<Map> _entriesBox;

  @override
  Future<Either<Failure, Entry>> create({
    required String content,
    required EntrySource source,
    int? mediaDurationSeconds,
    String? chatMessageId,
  }) async {
    final result = await _remoteDataSource.create(
      content: content,
      source: source,
      mediaDurationSeconds: mediaDurationSeconds,
      chatMessageId: chatMessageId,
    );
    return result.match((failure) async => left(failure), (dto) async {
      // A thrown Hive/disk exception must never escape unmapped (RNF09) —
      // same rationale/fallback `AuthRepositoryImpl` already uses for its
      // own local-persistence step.
      try {
        await _entriesBox.put(dto.id, dto.toJson());
      } catch (error) {
        return left(Failure.malformedResponse(message: error.toString()));
      }
      return right(_toEntry(dto));
    });
  }

  @override
  Future<Either<Failure, EntriesPage>> list({
    String? cursor,
    int limit = 20,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
  }) async {
    final result = await _remoteDataSource.list(
      cursor: cursor,
      limit: limit,
      source: source,
      dateFrom: dateFrom,
      dateTo: dateTo,
    );
    return result.match(
      (failure) async {
        // Boundaries/Design Notes: the Hive-cache fallback is scoped to
        // `cursor == null` (the first/fresh page) only — a paginated
        // continuation (`cursor != null`) that fails with
        // `networkOffline`/`networkTimeout` propagates as `Left` like any
        // other pagination failure instead, so `MeusRegistrosCubit`'s own
        // `loadMoreFailed`/retry path handles it uniformly rather than a
        // full unrelated cache dump silently replacing the in-progress
        // paginated list (and breaking its newest-first ordering).
        if (cursor == null &&
            (failure is NetworkOffline || failure is NetworkTimeout)) {
          return _offlineFallback();
        }
        return left(failure);
      },
      (page) async {
        try {
          await _entriesBox.putAll({
            for (final dto in page.items) dto.id: dto.toJson(),
          });
        } catch (error) {
          // Same RNF09 rationale as `create()`'s own Hive-write guard — a
          // thrown Hive/disk exception must never escape unmapped.
          return left(Failure.malformedResponse(message: error.toString()));
        }
        return right(
          EntriesPage(
            items: page.items.map(_toEntry).toList(),
            nextCursor: page.nextCursor,
          ),
        );
      },
    );
  }

  @override
  Future<Either<Failure, Entry>> getById(String id) async {
    final result = await _remoteDataSource.get(id);
    return result.match(
      (failure) async {
        // Boundaries: scoped to networkOffline/networkTimeout specifically
        // — every other Failure (notFound included) propagates as Left,
        // unmapped, same convention `list()`'s own cursor-scoped fallback
        // above uses.
        if (failure is NetworkOffline || failure is NetworkTimeout) {
          return _cachedEntryOrOriginalFailure(id, failure);
        }
        return left(failure);
      },
      (dto) async {
        // Same RNF09 rationale as `create()`/`list()`'s own Hive-write
        // guards — a thrown Hive/disk exception must never escape
        // unmapped.
        try {
          await _entriesBox.put(dto.id, dto.toJson());
        } catch (error) {
          return left(Failure.malformedResponse(message: error.toString()));
        }
        return right(_toEntry(dto));
      },
    );
  }

  @override
  Future<Either<Failure, List<Entry>>> search(
    String query, {
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
  }) async {
    final result = await _remoteDataSource.search(
      query,
      source: source,
      dateFrom: dateFrom,
      dateTo: dateTo,
    );
    return result.match(
      (failure) async {
        // Boundaries/AD-9: no cache fallback for search, unlike
        // list()/getById() — every Failure (including
        // networkOffline/networkTimeout) propagates as Left, unmapped.
        return left(failure);
      },
      (dtos) async {
        // Review finding: de-duplicated by id first (first-occurrence-wins,
        // same semantics as `MeusRegistrosCubit`'s own trust-but-verify
        // convention for server data, shared via `core/utils/
        // deduped_by_id.dart`) — so the `putAll` below and the returned
        // list stay consistent, and `_SearchResults`' `ListView.builder`
        // (keyed by `ValueKey(entry.id)`) never sees a duplicate key even
        // if the backend ever violated its own no-duplicate-ids invariant.
        final dedupedDtos = dedupedById(dtos, (dto) => dto.id);
        // Same RNF09 rationale as create()/list()/getById()'s own
        // Hive-write guards — a thrown Hive/disk exception must never
        // escape unmapped.
        try {
          await _entriesBox.putAll({
            for (final dto in dedupedDtos) dto.id: dto.toJson(),
          });
        } catch (error) {
          return left(Failure.malformedResponse(message: error.toString()));
        }
        return right(dedupedDtos.map(_toEntry).toList());
      },
    );
  }

  /// [getById]'s own offline/timeout fallback (Boundaries): a cache hit
  /// returns `Right` from the cached `EntryDto`; a cache miss propagates
  /// [originalFailure] unchanged — "no synthesized not-found" — rather than
  /// inventing a [Failure.notFound] this repository never actually
  /// received from the backend. A corrupt cached entry (should never
  /// happen — every entry here was written by [create]/[list]/[getById]
  /// themselves) maps to `Left(malformedResponse)` rather than throwing
  /// (RNF09), same guard `_offlineFallback()`'s own malformed-cache check
  /// uses.
  Either<Failure, Entry> _cachedEntryOrOriginalFailure(
    String id,
    Failure originalFailure,
  ) {
    try {
      final cached = _entriesBox.get(id);
      if (cached == null) {
        return left(originalFailure);
      }
      return right(
        _toEntry(EntryDto.fromJson(Map<String, dynamic>.from(cached))),
      );
    } catch (error) {
      return left(Failure.malformedResponse(message: error.toString()));
    }
  }

  /// The offline/timeout fallback (Boundaries): a full `entries` Hive box
  /// dump, sorted `occurredAt` desc, always `nextCursor: null` — a cached
  /// dump has no further page to request. A corrupt cached entry (should
  /// never happen — every entry here was written by [create]/[list]
  /// themselves) maps to `Left(malformedResponse)` rather than throwing
  /// (RNF09), same guard `create()`'s own Hive write already has.
  Either<Failure, EntriesPage> _offlineFallback() {
    try {
      final entries =
          _entriesBox.values
              .map(
                (json) => _toEntry(
                  EntryDto.fromJson(Map<String, dynamic>.from(json)),
                ),
              )
              .toList()
            ..sort(
              (a, b) =>
                  DateTime.parse(b.occurredAt)
                      .compareTo(DateTime.parse(a.occurredAt)),
            );
      return right(EntriesPage(items: entries, nextCursor: null));
    } catch (error) {
      return left(Failure.malformedResponse(message: error.toString()));
    }
  }

  @override
  Future<Either<Failure, Unit>> clearLocalCache() async {
    try {
      await _entriesBox.clear();
      return right(unit);
    } catch (error) {
      // Same RNF09 rationale as every other Hive-write guard in this file.
      return left(Failure.malformedResponse(message: error.toString()));
    }
  }

  Entry _toEntry(EntryDto dto) => Entry(
    id: dto.id,
    content: dto.content,
    source: dto.source,
    chatMessageId: dto.chatMessageId,
    occurredAt: dto.occurredAt,
    serverRevision: dto.serverRevision,
    createdAt: dto.createdAt,
    updatedAt: dto.updatedAt,
    mediaDurationSeconds: dto.mediaDurationSeconds,
  );
}

import 'package:hive_ce/hive_ce.dart';

import '../../core/di/injection_container.dart';
import '../../core/network/api_client.dart';
import '../auth/domain/repositories/session_repository.dart';
import 'data/datasources/entries_remote_data_source.dart';
import 'data/repositories/entries_repository_impl.dart';
import 'domain/repositories/entries_repository.dart';
import 'domain/services/pending_entry_write_tracker.dart';
import 'domain/usecases/save_chat_message_as_entry_use_case.dart';
import 'presentation/cubit/entries_search_cubit.dart';
import 'presentation/cubit/entry_detail_cubit.dart';
import 'presentation/cubit/meus_registros_cubit.dart';

/// The `entries` Hive box's name — the first `hive_ce` box in the app
/// (Code Map). A raw `Box<Map>`, not a generated `HiveObject`/
/// `TypeAdapter` (Design Notes: avoids adapter codegen) — spec-4-1's
/// `EntriesRepositoryImpl.list()` is this box's first reader
/// (`create()`'s own writes were, until then, never read back by
/// anything).
const entriesBoxName = 'entries';

/// Registers the `entries` feature into the project's single `get_it`
/// instance (`sl`) — mirrors `features/account/account_injection.dart`'s
/// pattern. Called from `setupCoreDependencies()` right after
/// `Hive.initFlutter()` (Code Map), which must already have run by the
/// time this opens its box.
Future<void> registerEntriesFeature() async {
  final entriesBox = await Hive.openBox<Map>(entriesBoxName);
  sl.registerSingleton<Box<Map>>(entriesBox);

  sl.registerLazySingleton<EntriesRemoteDataSource>(
    () => EntriesRemoteDataSource(sl<ApiClient>()),
  );

  sl.registerLazySingleton<EntriesRepository>(
    () => EntriesRepositoryImpl(
      remoteDataSource: sl<EntriesRemoteDataSource>(),
      entriesBox: sl<Box<Map>>(),
    ),
  );

  // spec-4-2 — one shared tracker for all three capture cubits
  // (`capture_injection.dart`) *and* `MeusRegistrosCubit` below, so a
  // pending write started from any capture cubit is visible to the other
  // regardless of which "+" tap created it (Design Notes).
  sl.registerLazySingleton<PendingEntryWriteTracker>(
    () => PendingEntryWriteTrackerImpl(repository: sl<EntriesRepository>()),
    dispose: (tracker) => tracker.dispose(),
  );

  // spec-6-4 (RF10) — the shared use case `ChatCubit.bookmarkMessage`
  // depends on (AGENTS.md's RF10 rule), registered here (not in
  // `chat_injection.dart`) since it wraps `EntriesRepository`, the entries
  // feature's own port; `registerChatFeature()` runs after this one
  // (`injection_container.dart`), so `sl<SaveChatMessageAsEntryUseCase>()`
  // is always already registered by the time `chat_injection.dart` wires
  // it into `ChatCubit`.
  sl.registerLazySingleton<SaveChatMessageAsEntryUseCase>(
    () => SaveChatMessageAsEntryUseCaseImpl(sl<EntriesRepository>()),
  );

  // spec-4-1 — `MeusRegistrosCubit` is a `lazySingleton`, not a factory
  // (Code Map/Boundaries), like `AccountSettingsCubit`: long-lived, so
  // `dispose:` wires its `close()` into `get_it`'s own reset lifecycle,
  // same convention `account_injection.dart` already uses.
  sl.registerLazySingleton<MeusRegistrosCubit>(
    () => MeusRegistrosCubit(
      sl<EntriesRepository>(),
      sl<PendingEntryWriteTracker>(),
    ),
    dispose: (cubit) => cubit.close(),
  );

  // spec-5-1 — `EntriesSearchCubit` is a `lazySingleton` too (Code Map),
  // mirroring `MeusRegistrosCubit` immediately above: long-lived, so
  // `dispose:` wires its `close()` into `get_it`'s own reset lifecycle the
  // same way.
  sl.registerLazySingleton<EntriesSearchCubit>(
    () => EntriesSearchCubit(sl<EntriesRepository>()),
    dispose: (cubit) => cubit.close(),
  );

  // spec-4-4 — a `factory`, not a `lazySingleton` (Code Map): each visit to
  // `/meus-registros/:id` gets its own throwaway instance
  // (`EntryDetailScreen`'s own `dispose()` closes it), mirroring the
  // capture cubits' own factory shape rather than `MeusRegistrosCubit`'s
  // long-lived one.
  sl.registerFactory<EntryDetailCubit>(
    () => EntryDetailCubit(
      sl<EntriesRepository>(),
      sl<PendingEntryWriteTracker>(),
      sl<SessionRepository>(),
    ),
  );
}

1	// The constructor keeps a public named param (`recorder`) distinct from
2	// the private field it initializes, matching
3	// `vault_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:io';
6	
7	import 'package:path_provider/path_provider.dart';
8	// Aliased — `record`'s own `AudioRecorder` would otherwise clash with
9	// nothing in this file today, but the alias keeps every reference to the
10	// package explicit, per Code Map.
11	import 'package:record/record.dart' as record_pkg;
12	
13	import '../../domain/services/mic_recorder.dart';
14	
15	/// Wraps `package:record`'s `AudioRecorder` behind the [MicRecorder] port.
16	/// A `get_it` singleton (Code Map/`capture_injection.dart`) — one real
17	/// recorder for the app's lifetime, reused across every Insertion Modal
18	/// open, never recreated per "+" tap the way `AudioEntryCubit` itself is.
19	class RecordMicRecorder implements MicRecorder {
20	  RecordMicRecorder({
21	    required record_pkg.AudioRecorder recorder,
22	    DateTime Function() now = DateTime.now,
23	  }) : _recorder = recorder,
24	       _now = now;
25	
26	  final record_pkg.AudioRecorder _recorder;
27	
28	  /// Injectable clock (Review finding) — same convention as
29	  /// `VaultRepositoryImpl`'s own `now` param — so a test can drive
30	  /// [stop]'s negative-duration clamp without waiting on, or faking, the
31	  /// real wall clock.
32	  final DateTime Function() _now;
33	
34	  /// Set by [start], cleared by [stop]/[cancel] — [stop] has no other way
35	  /// to learn how long the session ran, since `AudioRecorder.stop()` only
36	  /// ever returns the output path.
37	  DateTime? _startedAt;
38	
39	  /// Set by [start], cleared by [stop]/[cancel] — tracked independently
40	  /// of `_recorder`'s own "delete on cancel" contract (Review finding:
41	  /// that contract was asserted in this class's own doc comment but
42	  /// never independently verified) so [cancel] can delete the file
43	  /// itself rather than relying solely on the plugin's behavior.
44	  String? _currentPath;
45	
46	  @override
47	  Future<bool> hasPermission() => _recorder.hasPermission();
48	
49	  @override
50	  Future<void> start() async {
51	    final dir = await getTemporaryDirectory();
52	    final path =
53	        '${dir.path}/cerne_audio_entry_'
54	        '${DateTime.now().microsecondsSinceEpoch}.wav';
55	    await _recorder.start(
56	      // 16kHz mono matches `whisper_ggml`'s own expected input exactly
57	      // (its internal ffmpeg conversion step — `WhisperAudioConvert` —
58	      // falls back to passing the file through unconverted when ffmpeg
59	      // is unavailable, which only works if it's already in this shape).
60	      const record_pkg.RecordConfig(
61	        encoder: record_pkg.AudioEncoder.wav,
62	        sampleRate: 16000,
63	        numChannels: 1,
64	      ),
65	      path: path,
66	    );
67	    _startedAt = _now();
68	    _currentPath = path;
69	  }
70	
71	  @override
72	  Future<MicRecording?> stop() async {
73	    final path = await _recorder.stop();
74	    final startedAt = _startedAt;
75	    _startedAt = null;
76	    _currentPath = null;
77	    if (path == null || startedAt == null) {
78	      return null;
79	    }
80	    // Review finding: a backward system-clock adjustment mid-recording
81	    // (DST/NTP correction) could otherwise make this negative, which the
82	    // backend's `mediaDurationSeconds: minimum 0` contract rejects —
83	    // floored at 0 rather than trusting the wall clock never moves back.
84	    final elapsed = _now().difference(startedAt).inSeconds;
85	    return MicRecording(path: path, durationSeconds: elapsed < 0 ? 0 : elapsed);
86	  }
87	
88	  @override
89	  Future<void> cancel() async {
90	    _startedAt = null;
91	    final path = _currentPath;
92	    _currentPath = null;
93	    await _recorder.cancel();
94	    // Review finding: don't rely solely on the plugin's own "cancel
95	    // deletes the file" contract — delete it ourselves too, best-effort,
96	    // so this class's own doc comment stays true regardless of the
97	    // underlying plugin's actual behavior.
98	    if (path != null) {
99	      try {
100	        await File(path).delete();
101	      } catch (_) {
102	        // Best-effort — the plugin may have already deleted it itself,
103	        // or it may never have existed (e.g. a very early cancel).
104	      }
105	    }
106	  }
107	
108	  @override
109	  Stream<double> get amplitudeStream => _recorder
110	      .onAmplitudeChanged(const Duration(milliseconds: 200))
111	      .map(_normalize);
112	
113	  /// `record`'s own `Amplitude.current` is dBFS, roughly -45 (near
114	  /// silence, in practice — the package's own floor is -160 but normal
115	  /// mic noise never gets that quiet) to 0 (loudest) — rescaled to a
116	  /// 0.0–1.0 range the waveform widget can use directly, with no
117	  /// `package:record` type ever crossing the [MicRecorder] boundary.
118	  double _normalize(record_pkg.Amplitude amplitude) {
119	    const floorDb = -45.0;
120	    final clamped = amplitude.current.clamp(floorDb, 0.0);
121	    return (clamped - floorDb) / -floorDb;
122	  }
123	}
124

