2	// the private field it initializes, matching
3	// `vault_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'package:whisper_ggml/whisper_ggml.dart';
6	
7	import '../../domain/services/audio_transcriber.dart';
8	
9	/// Wraps `whisper_ggml`'s `WhisperController` behind the [AudioTranscriber]
10	/// port — 100% on-device (FR-12), `lang: 'pt'`, `WhisperModel.base`
11	/// (Design Notes: balances accuracy/size). A `get_it` singleton (Code Map/
12	/// `capture_injection.dart`), same "one real instance for the app's
13	/// lifetime" convention as [RecordMicRecorder].
14	class WhisperAudioTranscriber implements AudioTranscriber {
15	  WhisperAudioTranscriber({required WhisperController controller})
16	    : _controller = controller;
17	
18	  final WhisperController _controller;
19	
20	  static const _model = WhisperModel.base;
21	
22	  @override
23	  Future<String?> transcribe(String audioPath) async {
24	    try {
25	      // Lazy download, inside transcribe() (Design Notes) — a missing
26	      // model + no connectivity just surfaces through the catch below,
27	      // same generic error/retry path as any other transcription
28	      // failure.
29	      await _controller.downloadModel(_model);
30	      final result = await _controller.transcribe(
31	        model: _model,
32	        audioPath: audioPath,
33	        lang: 'pt',
34	      );
35	      // `WhisperController.transcribe` already swallows its own internal
36	      // exceptions into a `null` return (never throws) — the outer `try`
37	      // here exists for `downloadModel`'s own exceptions (e.g. no
38	      // connectivity on first-ever use), not this call.
39	      return result?.transcription.text;
40	    } catch (_) {
41	      return null;
42	    }
43	  }
44	}
