1	import 'dart:async';
2	import 'dart:io';
3	
4	import 'package:flutter_bloc/flutter_bloc.dart';
5	
6	import '../../../entries/domain/entities/entry.dart';
7	import '../../../entries/domain/services/pending_entry_write_tracker.dart';
8	import '../../domain/services/audio_transcriber.dart';
9	import '../../domain/services/mic_recorder.dart';
10	
11	/// `AudioEntryCubit`'s own sealed state hierarchy — separate from
12	/// `TextEntryState` (Boundaries: "own sealed `AudioCaptureState`,
13	/// separate from `TextEntryState`"). Unlike `TextEntryState`, no common
14	/// base-class field: the 5 variants don't share a uniform shape the way
15	/// every `TextEntryState` always carries `activeTab`/`text` — [AudioIdle]
16	/// genuinely has nothing in common with [AudioTranscribed], for instance.
17	sealed class AudioCaptureState {
18	  const AudioCaptureState();
19	}
20	
21	/// The state a fresh `AudioEntryCubit` always starts in, and the state
22	/// reached after leaving the tab mid-recording (`cancel()`). Rendered by
23	/// `InsertionModal`'s own `_AudioIdleView` as the prototype's round
24	/// microphone button over "Toque para gravar" — [AudioEntryCubit.
25	/// startRecording] only ever runs once the user taps it (correction:
26	/// entering the tab previously called it automatically).
27	class AudioIdle extends AudioCaptureState {
28	  const AudioIdle();
29	}
30	
31	/// Recording in progress — [elapsedSeconds] backs the running monospace
32	/// timer (Acceptance Criteria) and ticks once per second via
33	/// `AudioEntryCubit`'s own internal `Timer.periodic`.
34	class AudioRecording extends AudioCaptureState {
35	  const AudioRecording({required this.elapsedSeconds});
36	
37	  final int elapsedSeconds;
38	}
39	
40	/// Recording stopped, `AudioTranscriber.transcribe()` in flight —
41	/// `InsertionModal`'s own `_AudioTab` freezes the waveform at 35% opacity
42	/// for the whole duration of this state (Acceptance Criteria).
43	class AudioProcessing extends AudioCaptureState {
44	  const AudioProcessing({required this.path, required this.durationSeconds});
45	
46	  final String path;
47	  final int durationSeconds;
48	}
49	
50	/// Transcription succeeded (even to an empty string) — [text] is editable
51	/// before Salvar (Acceptance Criteria), mirrored into this state by
52	/// `AudioEntryCubit.updateText` the same way `TextEntryCubit.updateText`
53	/// mirrors the Texto field. [saving] is this story's `TextEntrySaving`
54	/// equivalent folded into one state instead of a separate sibling class —
55	/// both [path]/[durationSeconds] (needed for the eventual `create()` call)
56	/// stay fixed across a save attempt, so there's nothing a sibling state
57	/// would add that a boolean field doesn't already cover just as clearly.
58	class AudioTranscribed extends AudioCaptureState {
59	  const AudioTranscribed({
60	    required this.path,
61	    required this.durationSeconds,
62	    required this.text,
63	    required this.saving,
64	  });
65	
66	  final String path;
67	  final int durationSeconds;
68	  final String text;
69	  final bool saving;
70	
71	  AudioTranscribed copyWith({String? text, bool? saving}) => AudioTranscribed(
72	    path: path,
73	    durationSeconds: durationSeconds,
74	    text: text ?? this.text,
75	    saving: saving ?? this.saving,
76	  );
77	}
78	
79	/// A save attempt from [AudioTranscribed] succeeded — `InsertionModal`'s
80	/// listener reacts to this exactly like `TextEntrySaved` (announce, then
81	/// pop). Terminal, same rationale as `TextEntrySaved`'s own doc.
82	class AudioSaved extends AudioCaptureState {
83	  const AudioSaved();
84	}
85	
86	/// The last attempt failed — covers all 3 failure rows of the I/O matrix:
87	/// - Mic permission denied -> [path]/[durationSeconds] both `null` ("No
88	///   file to preserve"); [AudioEntryCubit.retry] re-requests permission.
89	/// - Transcription failed -> [path]/[durationSeconds] carry the preserved
90	///   file; [AudioEntryCubit.retry] re-transcribes it, never re-records.
91	/// - Save failed (incl. offline) -> same preserved [path]/
92	///   [durationSeconds]/[text] semantics as `TextEntryError`; the modal's
93	///   `_AudioTab` keeps showing the editable text with Salvar re-enabled
94	///   rather than routing back through [AudioEntryCubit.retry].
95	class AudioError extends AudioCaptureState {
96	  const AudioError({
97	    required this.path,
98	    required this.durationSeconds,
99	    required this.message,
100	    this.text,
101	  });
102	
103	  final String? path;
104	  final int? durationSeconds;
105	  final String message;
106	
107	  /// Non-null only for a save failure — lets `_AudioTab` keep rendering
108	  /// the editable text field under the inline error, same as
109	  /// `TextEntryError`'s own `_TextoTab` rendering.
110	  final String? text;
111	}
112	
113	/// Drives the Áudio tab's recording -> processing -> transcribed/error
114	/// pipeline (Intent). A fresh, `get_it`-factory-scoped instance per "+"
115	/// tap, same convention as `TextEntryCubit` — [MicRecorder]/
116	/// [AudioTranscriber] themselves stay long-lived `get_it` singletons
117	/// (`capture_injection.dart`), shared across every modal open the way
118	/// `EntriesRepository` already is for `TextEntryCubit`.
119	class AudioEntryCubit extends Cubit<AudioCaptureState> {
120	  AudioEntryCubit(this._micRecorder, this._audioTranscriber, this._tracker)
121	    : super(const AudioIdle());
122	
123	  final MicRecorder _micRecorder;
124	  final AudioTranscriber _audioTranscriber;
125	
126	  /// spec-4-2 — the shared [PendingEntryWriteTracker], swapped in for a
127	  /// direct `EntriesRepository` dependency (identical `create()` contract,
128	  /// Code Map: "no call-site logic change").
129	  final PendingEntryWriteTracker _tracker;
130	
131	  Timer? _elapsedTimer;
132	
133	  /// Bumped by [cancel] so an in-flight [startRecording]/[stopRecording]
134	  /// continuation can tell "the user already left the Áudio tab while I
135	  /// was awaiting" apart from "nothing has changed since I started" —
136	  /// the same role `isClosed` already plays for `close()`, but for a tab
137	  /// switch that doesn't close the cubit itself (Review finding: without
138	  /// this, `cancel()` running mid-await either left the recorder running
139	  /// unobserved, or let a stale `stop()`/transcription result resurrect a
140	  /// flow the user already left).
141	  int _generation = 0;
142	
143	  /// Guards [stopRecording] against a second concurrent call (e.g. a fast
144	  /// double-tap on the stop control before the UI rebuilds past
145	  /// [AudioRecording]) — without this, a second `_micRecorder.stop()` call
146	  /// racing the first could return `null` (nothing left to stop) and
147	  /// overwrite a perfectly good [AudioProcessing]/transcription result
148	  /// with a bogus [AudioError] (Review finding).
149	  bool _stopping = false;
150	
151	  /// Forwarded straight from [MicRecorder.amplitudeStream] — lets
152	  /// `_AudioTab`'s waveform animate without ever importing `package:record`
153	  /// itself (Boundaries).
154	  Stream<double> get amplitudeStream => _micRecorder.amplitudeStream;
155	
156	  /// Starts recording — called from `InsertionModal`'s own
157	  /// `_AudioIdleView` the moment the user taps the idle mic button
158	  /// (correction: a previous pass called this automatically from the
159	  /// tab-switch listener instead), and again by [retry] when the last
160	  /// attempt failed before any file ever existed (permission
161	  /// denied). Ignored while a recording is already in progress, and —
162	  /// Review finding — ignored once the pipeline has moved past recording
163	  /// ([AudioProcessing]/[AudioTranscribed]/an [AudioError] that still
164	  /// carries a file): without this, re-entering the Áudio tab after a
165	  /// completed transcription silently discarded the transcribed text and
166	  /// started a brand-new recording over it. Only [AudioIdle] (fresh) or
167	  /// an [AudioError] with no file (nothing to discard) actually start.
168	  Future<void> startRecording() async {
169	    final current = state;
170	    final canStart =
171	        current is AudioIdle || (current is AudioError && current.path == null);
172	    if (!canStart) {
173	      return;
174	    }
175	    final generation = ++_generation;
176	    bool hasPermission;
177	    try {
178	      hasPermission = await _micRecorder.hasPermission();
179	    } catch (_) {
180	      // Review finding: a thrown `PlatformException` (native-side error)
181	      // must never escape uncaught — surfaces through the same
182	      // error/retry path as a plain permission denial.
183	      if (isClosed || generation != _generation) {
184	        return;
185	      }
186	      emit(
187	        const AudioError(
188	          path: null,
189	          durationSeconds: null,
190	          message: 'Não foi possível acessar o microfone.',
191	        ),
192	      );
193	      return;
194	    }
195	    if (isClosed || generation != _generation) {
196	      return;
197	    }
198	    if (!hasPermission) {
199	      emit(
200	        const AudioError(
201	          path: null,
202	          durationSeconds: null,
203	          message:
204	              'Permissão de microfone negada. Toque em "Tentar novamente" '
205	              'para permitir o acesso.',
206	        ),
207	      );
208	      return;
209	    }
210	    try {
211	      await _micRecorder.start();
212	    } catch (_) {
213	      // Review finding: same rationale as the `hasPermission()` catch
214	      // above — a native-side start failure must surface through the
215	      // normal error/retry path instead of escaping uncaught.
216	      if (isClosed || generation != _generation) {
217	        // Review finding: the shared `_micRecorder` singleton may already
218	        // belong to a newer, currently-active generation by the time this
219	        // stale catch fires — never release it from here, only from the
220	        // generation that's still actually live, or this would silently
221	        // kill a different, active recording with no error surfaced.
222	        return;
223	      }
224	      // Also releases the native recorder best-effort (Review finding): a
225	      // partial/failed `start()` may still have left a session open.
226	      unawaited(_safeCancelRecorder());
227	      emit(
228	        const AudioError(
229	          path: null,
230	          durationSeconds: null,
231	          message: 'Não foi possível iniciar a gravação.',
232	        ),
233	      );
234	      return;
235	    }
236	    if (isClosed || generation != _generation) {
237	      // Review finding: `cancel()` bumped `_generation` (the user already
238	      // left the Áudio tab) while `start()` was in flight — stop/discard
239	      // the session we just started instead of leaving a live, unobserved
240	      // recording running.
241	      unawaited(_safeCancelRecorder());
242	      return;
243	    }
244	    _startElapsedTimer();
245	    emit(const AudioRecording(elapsedSeconds: 0));
246	  }
247	
248	  void _startElapsedTimer() {
249	    _elapsedTimer?.cancel();
250	    var elapsed = 0;
251	    _elapsedTimer = Timer.periodic(const Duration(seconds: 1), (_) {
252	      elapsed++;
253	      if (state is AudioRecording) {
254	        emit(AudioRecording(elapsedSeconds: elapsed));
255	      }
256	    });
257	  }
258	
259	  /// Stops recording and immediately kicks off transcription — the I/O
260	  /// matrix's "Happy path"/"Transcription fails" rows. Ignored outside
261	  /// [AudioRecording] (e.g. a stray second tap on the stop control) and
262	  /// — Review finding — ignored while a previous call is still awaiting
263	  /// `_micRecorder.stop()` ([_stopping]): without this, a fast double-tap
264	  /// on the stop control could fire a second `_micRecorder.stop()` call
265	  /// that returns `null` (nothing left to stop) and clobber the first
266	  /// call's genuine result with a bogus `AudioError`.
267	  Future<void> stopRecording() async {
268	    if (state is! AudioRecording || _stopping) {
269	      return;
270	    }
271	    _stopping = true;
272	    final generation = _generation;
273	    _elapsedTimer?.cancel();
274	    MicRecording? recording;
275	    try {
276	      recording = await _micRecorder.stop();
277	    } catch (_) {
278	      // Review finding: a thrown `PlatformException` must never escape
279	      // uncaught — surfaces through the normal error/retry path instead.
280	      _stopping = false;
281	      if (isClosed || generation != _generation) {
282	        // Review finding: the shared `_micRecorder` singleton may already
283	        // belong to a newer, currently-active generation by the time this
284	        // stale catch fires — never release it from here, only from the
285	        // generation that's still actually live, or this would silently
286	        // kill a different, active recording with no error surfaced.
287	        return;
288	      }
289	      // Also releases the native recorder best-effort (Review finding): a
290	      // failed `stop()` leaves the actual native session state
291	      // unconfirmed, so this is the only chance to try to release it.
292	      unawaited(_safeCancelRecorder());
293	      emit(
294	        const AudioError(
295	          path: null,
296	          durationSeconds: null,
297	          message: 'Não foi possível gravar o áudio.',
298	        ),
299	      );
300	      return;
301	    }
302	    _stopping = false;
303	    // Review finding: without the `_generation` check, a `cancel()` that
304	    // ran while `_micRecorder.stop()` was in flight (tab switch right
305	    // after tapping stop) already reset the cubit to `AudioIdle` — this
306	    // continuation must not resurrect the flow with a stale
307	    // `AudioProcessing`/`AudioError` emission on top of that reset.
308	    if (isClosed || generation != _generation) {
309	      return;
310	    }
311	    if (recording == null) {
312	      // Stopped with nothing actually captured — the I/O matrix has no
313	      // dedicated row for this (it should be unreachable in practice: the
314	      // recorder was just started above), but `AudioError` with no file
315	      // still gives the user a path back in via retry's permission-
316	      // re-request branch rather than leaving the cubit stuck mid-flow.
317	      emit(
318	        const AudioError(
319	          path: null,
320	          durationSeconds: null,
321	          message: 'Não foi possível gravar o áudio.',
322	        ),
323	      );
324	      return;
325	    }
326	    emit(
327	      AudioProcessing(
328	        path: recording.path,
329	        durationSeconds: recording.durationSeconds,
330	      ),
331	    );
332	    await _transcribe(recording.path, recording.durationSeconds);
333	  }
334	
335	  Future<void> _transcribe(String path, int durationSeconds) async {
336	    final text = await _audioTranscriber.transcribe(path);
337	    if (isClosed) {
338	      return;
339	    }
340	    // Guards a tab switch away mid-processing (`cancel()`, below) that
341	    // already reset the state to `AudioIdle` by the time this resolves —
342	    // without this, the eventual transcription result would still land
343	    // and resurrect a flow the user already left.
344	    if (state is! AudioProcessing || (state as AudioProcessing).path != path) {
345	      return;
346	    }
347	    if (text == null) {
348	      emit(
349	        AudioError(
350	          path: path,
351	          durationSeconds: durationSeconds,
352	          message: 'Não foi possível transcrever o áudio.',
353	        ),
354	      );
355	      return;
356	    }
357	    emit(
358	      AudioTranscribed(
359	        path: path,
360	        durationSeconds: durationSeconds,
361	        text: text,
362	        saving: false,
363	      ),
364	    );
365	  }
366	
367	  /// "Tentar novamente" — re-requests permission when no file was ever
368	  /// recorded, or re-transcribes the same preserved file otherwise (I/O
369	  /// matrix: never re-records, never auto-retries on its own). A no-op
370	  /// outside [AudioError], or for a save failure (non-null [AudioError.
371	  /// text]) — that case's own retry is just tapping Salvar again, handled
372	  /// by [save] directly, not this method.
373	  Future<void> retry() async {
374	    final current = state;
375	    if (current is! AudioError || current.text != null) {
376	      return;
377	    }
378	    final path = current.path;
379	    final durationSeconds = current.durationSeconds;
380	    if (path == null || durationSeconds == null) {
381	      await startRecording();
382	      return;
383	    }
384	    emit(AudioProcessing(path: path, durationSeconds: durationSeconds));
385	    await _transcribe(path, durationSeconds);
386	  }
387	
388	  /// Mirrors the Texto field's own `updateText` — keeps the transcribed
389	  /// text editable before Salvar (Acceptance Criteria). Ignored while a
390	  /// save is already in flight, same rationale as `TextEntryCubit.
391	  /// updateText`.
392	  void updateText(String text) {
393	    final current = state;
394	    if (current is AudioTranscribed && !current.saving) {
395	      emit(current.copyWith(text: text));
396	    } else if (current is AudioError && current.text != null) {
397	      // Review finding: a save failure (`AudioError` with non-null
398	      // `text`) renders the same editable field as `AudioTranscribed`
399	      // (`_AudioErrorView`'s non-retry branch) — without this branch,
400	      // typing there updated the `TextField`'s own controller visually
401	      // but never the cubit's record of the text, so a retried `save()`
402	      // would silently resend the stale pre-failure text.
403	      emit(
404	        AudioError(
405	          path: current.path,
406	          durationSeconds: current.durationSeconds,
407	          message: current.message,
408	          text: text,
409	        ),
410	      );
411	    }
412	  }
413	
414	  /// Called when the Áudio tab loses focus mid-recording/mid-processing
415	  /// (`InsertionModal`'s tab-switch listener) — the I/O matrix's "Leave
416	  /// tab mid-recording" row: stops/releases the recorder, no `create()`
417	  /// ever fires. A no-op for every other state when [discardPreserved] is
418	  /// `false` (the default) — in particular [AudioTranscribed]/[AudioError],
419	  /// where the Never clause's trivial scope (resource safety only, not
420	  /// full Story 3.4 cancel-safety) means a tab switch must preserve the
421	  /// result rather than discard it.
422	  ///
423	  /// [discardPreserved] — Review finding: `InsertionModal.show()`'s
424	  /// `finally` also calls this (before `close()`) when the *whole modal*
425	  /// is dismissed (✕/swipe-down/barrier tap), not just the tab. In that
426	  /// case there's no "switch back to the tab later" to preserve for —
427	  /// the cubit is about to be closed — so a preserved [AudioTranscribed]
428	  /// or file-carrying [AudioError]'s temp file would otherwise never be
429	  /// cleaned up and leak on disk forever. Pass `true` only from that
430	  /// call site.
431	  Future<void> cancel({bool discardPreserved = false}) async {
432	    // Bumped unconditionally — including when the state below doesn't
433	    // match either branch — so an in-flight `startRecording()`/
434	    // `stopRecording()` continuation still sees the mismatch and aborts
435	    // itself (Review finding: previously only invalidated a flow already
436	    // visible in `state`, missing the window while those methods were
437	    // still awaiting).
438	    _generation++;
439	    // Review finding: without this, a hung `_micRecorder.stop()` call
440	    // (one that never resolves) left `_stopping` stuck `true` forever —
441	    // `stopRecording()`'s own guard made it a permanent no-op for the
442	    // rest of this cubit's life. The `_generation` bump above already
443	    // makes that stale continuation's eventual result a no-op, so
444	    // resetting this eagerly is always safe, mirroring `PhotoEntryCubit.
445	    // cancel()`'s own `_picking = false` reset.
446	    _stopping = false;
447	    final current = state;
448	    if (current is AudioRecording) {
449	      _elapsedTimer?.cancel();
450	      await _safeCancelRecorder();
451	      if (isClosed) {
452	        return;
453	      }
454	      emit(const AudioIdle());
455	    } else if (current is AudioProcessing) {
456	      // The recorder itself is already stopped by the time this state is
457	      // reached (`stopRecording` stops it before emitting `AudioProcessing`)
458	      // — only resetting the cubit's own state is left, so the pending
459	      // `_transcribe` continuation's own `state is! AudioProcessing` guard
460	      // (above) drops its result instead of resurrecting this flow. Review
461	      // finding: the already-recorded file is abandoned for good at this
462	      // point (nothing will ever retry it), so it must be deleted here —
463	      // the other orphan-file case `_micRecorder.cancel()` above already
464	      // handles on its own.
465	      unawaited(_deleteRecordingFile(current.path));
466	      emit(const AudioIdle());
467	    } else if (discardPreserved) {
468	      final path = switch (current) {
469	        AudioTranscribed(path: final p) => p,
470	        AudioError(path: final p) => p,
471	        _ => null,
472	      };
473	      if (path != null) {
474	        unawaited(_deleteRecordingFile(path));
475	      }
476	    }
477	  }
478	
479	  /// Best-effort `_micRecorder.cancel()` — a thrown `PlatformException`
480	  /// here (Review finding) must never escape uncaught, since both call
481	  /// sites (above, and [startRecording]'s own abandon-on-generation-
482	  /// mismatch branch) call this fire-and-forget.
483	  Future<void> _safeCancelRecorder() async {
484	    try {
485	      await _micRecorder.cancel();
486	    } catch (_) {
487	      // Best-effort — nothing in the UI depends on this succeeding.
488	    }
489	  }
490	
491	  /// I/O matrix's "Happy path"/"Save fails" rows: fires `POST /entries`
492	  /// with `source: audio` and `mediaDurationSeconds` for the current
493	  /// transcribed text. Mirrors `TextEntryCubit.save()`'s `isClosed`/
494	  /// no-double-submit guards exactly (Boundaries).
495	  ///
496	  /// Review finding: also callable from an [AudioError] save failure
497	  /// (non-null [AudioError.text]) — `_AudioErrorView`'s non-retry branch
498	  /// re-renders the editable field and calls this same method for its
499	  /// "Salvar" button, but the original guard only matched
500	  /// [AudioTranscribed], making a retry after any save failure a
501	  /// permanent no-op.
502	  Future<void> save() async {
503	    final current = state;
504	    final String path;
505	    final int durationSeconds;
506	    final String text;
507	    if (current is AudioTranscribed && !current.saving) {
508	      path = current.path;
509	      durationSeconds = current.durationSeconds;
510	      text = current.text.trim();
511	    } else if (current is AudioError &&
512	        current.text != null &&
513	        current.path != null &&
514	        current.durationSeconds != null) {
515	      path = current.path!;
516	      durationSeconds = current.durationSeconds!;
517	      text = current.text!.trim();
518	    } else {
519	      return;
520	    }
521	    if (text.isEmpty) {
522	      return;
523	    }
524	    emit(
525	      AudioTranscribed(
526	        path: path,
527	        durationSeconds: durationSeconds,
528	        text: text,
529	        saving: true,
530	      ),
531	    );
532	    final result = await _tracker.create(
533	      content: text,
534	      source: EntrySource.audio,
535	      mediaDurationSeconds: durationSeconds,
536	    );
537	    // Mirrors `TextEntryCubit.save()`'s own `isClosed` guard — this
538	    // cubit's `close()` can race the awaited call above (e.g. the modal's
539	    // barrier is dismissed mid-save).
540	    if (isClosed) {
541	      return;
542	    }
543	    result.match(
544	      (failure) => emit(
545	        AudioError(
546	          path: path,
547	          durationSeconds: durationSeconds,
548	          message: failure.message,
549	          text: text,
550	        ),
551	      ),
552	      (_) {
553	        // Review finding: the recorded temp file was never deleted after
554	        // a successful save — fire-and-forget, a deletion failure must
555	        // never block the modal from closing.
556	        unawaited(_deleteRecordingFile(path));
557	        emit(const AudioSaved());
558	      },
559	    );
560	  }
561	
562	  /// Best-effort cleanup for a temp recording file this cubit is done
563	  /// with (saved successfully, or abandoned for good by [cancel] mid-
564	  /// processing) — deletion failures are swallowed since nothing in the
565	  /// UI depends on this succeeding (Review finding: previously never
566	  /// called at all, leaking a `.wav` file per recording indefinitely).
567	  Future<void> _deleteRecordingFile(String path) async {
568	    try {
569	      await File(path).delete();
570	    } catch (_) {
571	      // Best-effort — a missing/already-deleted file, or a transient
572	      // disk error, is never worth surfacing to the user.
573	    }
574	  }
575	
576	  @override
577	  Future<void> close() {
578	    _elapsedTimer?.cancel();
579	    return super.close();
580	  }
581	}
