21	/// Registers the `capture` feature into the project's single `get_it`
22	/// instance (`sl`). Unlike every other feature's cubit in this codebase
23	/// (`AccountSettingsCubit`/`AuthCubit`, lazy singletons), [TextEntryCubit]/
24	/// [AudioEntryCubit] are both **factories** — the Insertion Modal needs a
25	/// fresh instance of each per "+" tap (Boundaries: "Modal open resets"),
26	/// not one long-lived instance reused across opens. [MicRecorder]/
27	/// [AudioTranscriber] (and the raw `record`/`whisper_ggml` plugin
28	/// instances underneath them) stay lazy singletons instead — one real
29	/// recorder/transcriber for the app's lifetime, shared across every modal
30	/// open, mirroring `PendingEntryWriteTracker`'s own registration shape.
31	/// Called from `setupCoreDependencies()` right after
32	/// `registerEntriesFeature()` (Code Map) — that call must run first, since
33	/// [PendingEntryWriteTracker] is registered there.
34	///
35	/// spec-4-2 — all three cubit factories below depend on
36	/// [PendingEntryWriteTracker] instead of `EntriesRepository` directly
37	/// (Code Map: "swap `EntriesRepository` dep for tracker"); the tracker
38	/// itself calls through to `EntriesRepository.create()` internally, so no
39	/// call-site logic changes, only the dependency type.
40	void registerCaptureFeature() {
41	  sl.registerFactory<TextEntryCubit>(
42	    () => TextEntryCubit(sl<PendingEntryWriteTracker>()),
43	  );
44	
45	  sl.registerLazySingleton<record_pkg.AudioRecorder>(
46	    record_pkg.AudioRecorder.new,
47	  );
48	  sl.registerLazySingleton<MicRecorder>(
49	    () => RecordMicRecorder(recorder: sl<record_pkg.AudioRecorder>()),
50	  );
51	
52	  sl.registerLazySingleton<WhisperController>(WhisperController.new);
53	  sl.registerLazySingleton<AudioTranscriber>(
54	    () => WhisperAudioTranscriber(controller: sl<WhisperController>()),
55	  );
56	
57	  sl.registerFactory<AudioEntryCubit>(
58	    () => AudioEntryCubit(
59	      sl<MicRecorder>(),
60	      sl<AudioTranscriber>(),
61	      sl<PendingEntryWriteTracker>(),
62	    ),
63	  );
64	
65	  sl.registerLazySingleton<image_picker_pkg.ImagePicker>(
66	    image_picker_pkg.ImagePicker.new,
67	  );
68	  sl.registerLazySingleton<PhotoPicker>(
69	    () => ImagePickerPhotoPicker(picker: sl<image_picker_pkg.ImagePicker>()),
70	  );
71	
72	  sl.registerLazySingleton<MediaRemoteDataSource>(
73	    () => MediaRemoteDataSource(sl<ApiClient>()),
74	  );
75	  sl.registerLazySingleton<MediaRepository>(
76	    () => MediaRepositoryImpl(remoteDataSource: sl<MediaRemoteDataSource>()),
77	  );
78	
79	  sl.registerFactory<PhotoEntryCubit>(
80	    () => PhotoEntryCubit(
81	      sl<PhotoPicker>(),
82	      sl<MediaRepository>(),
83	      sl<PendingEntryWriteTracker>(),
84	    ),
85	  );
86	}
