153	  Future<void> _pick(Future<PickedPhoto?> Function() pick) async {
154	    final current = state;
155	    final canPick =
156	        !_picking &&
157	        (current is PhotoIdle ||
158	            (current is PhotoError &&
159	                current.kind == PhotoErrorKind.payloadTooLarge));
