167	    // finding): this old file is abandoned the moment a new pick starts,
168	    // regardless of whether that new pick succeeds, is canceled, or
169	    // throws — the earlier code only deleted it on success, leaking it
170	    // on every other exit path.
171	    final previousPath = current is PhotoError ? current.path : null;
172	    if (previousPath != null) {
173	      unawaited(_deletePickedFile(previousPath));
174	    }
175	    _picking = true;
176	    final generation = ++_generation;
177	    PickedPhoto? photo;
178	    try {
179	      photo = await pick();
180	    } catch (_) {
181	      // A thrown PlatformException (native-side error) must never escape
