192	    _picking = false;
193	    if (isClosed || generation != _generation) {
194	      // Review finding: without this, a photo picked just as the user
195	      // left the tab (or closed the whole modal) was discarded with no
196	      // cleanup — its OS temp file leaked forever.
197	      if (photo != null) {
