199	      }
200	      return;
201	    }
202	    if (photo == null) {
203	      // I/O matrix: "User cancels picker" -> stays on PhotoIdle's capture
204	      // buttons. If the re-pick was attempted from a `payloadTooLarge`
205	      // error, drop that stale error too rather than leaving it on
206	      // screen with nothing that produced it anymore.
207	      if (current is PhotoError) {
208	        emit(const PhotoIdle());
209	      }
210	      return;
211	    }
212	    emit(PhotoProcessing(path: photo.path, mimeType: photo.mimeType));
213	    await _recognize(photo.path, photo.mimeType, generation);
214	  }
