216	  Future<void> _recognize(String path, String mimeType, int generation) async {
217	    Uint8List bytes;
218	    try {
219	      bytes = await File(path).readAsBytes();
220	    } catch (_) {
221	      if (isClosed || generation != _generation) {
222	        return;
223	      }
224	      emit(
225	        PhotoError(
226	          path: path,
227	          mimeType: mimeType,
228	          message: 'Não foi possível ler a foto selecionada.',
229	          kind: PhotoErrorKind.generic,
230	        ),
231	      );
232	      return;
233	    }
234	    final result = await _mediaRepository.recognizeText(
235	      imageBytes: bytes,
236	      mimeType: mimeType,
237	    );
238	    // Guards a tab switch away mid-OCR (`cancel()`, below) that already
239	    // reset the state by the time this resolves — without this, a stale
240	    // OCR result would still land and resurrect a flow the user left.
241	    if (isClosed || generation != _generation) {
242	      return;
243	    }
244	    result.match(
245	      (failure) => emit(
246	        PhotoError(
247	          path: path,
248	          mimeType: mimeType,
249	          message: failure.message,
250	          kind: switch (failure) {
251	            OcrNoText() => PhotoErrorKind.ocrNoText,
252	            PayloadTooLarge() => PhotoErrorKind.payloadTooLarge,
253	            _ => PhotoErrorKind.generic,
254	          },
255	        ),
256	      ),
257	      (ocr) => emit(
258	        PhotoRecognized(
259	          path: path,
260	          mimeType: mimeType,
261	          text: ocr.text,
262	          saving: false,
263	        ),
264	      ),
265	    );
266	  }
