366	    // cubit's `close()` can race the awaited call above (e.g. the
367	    // modal's barrier is dismissed mid-save).
368	    if (isClosed) {
369	      return;
370	    }
371	    result.match(
372	      (failure) => emit(
373	        PhotoError(
374	          path: path,
375	          mimeType: mimeType,
376	          message: failure.message,
377	          kind: PhotoErrorKind.generic,
378	          text: text,
379	        ),
380	      ),
381	      (_) {
382	        // Review finding: the picked photo's temp file (written by
383	        // `image_picker` itself, not by this class, but still this
