14	/// The single `create()`/`retry()` entry point for all three capture
15	/// cubits (`TextEntryCubit`/`AudioEntryCubit`/`PhotoEntryCubit`) — Intent:
16	/// "the tracker, not `MeusRegistrosCubit`, owns reconciliation". Pure
17	/// Dart, no `package:flutter`/`data` import (RNF06) — a port+impl pair in
18	/// one file, same structural convention `SessionExpiryNotifier`/
19	/// `SessionExpiryNotifierImpl` already use.
20	abstract class PendingEntryWriteTracker {
21	  /// Identical contract to [EntriesRepository.create] (Boundaries) — every
22	  /// capture cubit swaps its `EntriesRepository` dependency for this one,
23	  /// with no other call-site change. Internally: records an optimistic
24	  /// [PendingEntryWrite] (status [PendingEntryWriteInFlight]) *before*
25	  /// calling through to the repository, so [pendingWrites] reflects it
26	  /// immediately; on success, drops the record and emits the confirmed
27	  /// [Entry] on [confirmedWrites]; on failure, flips the record to
28	  /// [PendingEntryWriteFailed] and leaves it for [retry].
29	  Future<Either<Failure, Entry>> create({
30	    required String content,
31	    required EntrySource source,
32	    int? mediaDurationSeconds,
33	  });
34	
35	  /// Replays the exact same payload a failed write ([tempId]) was created
36	  /// with (Never: "a second retry endpoint — retry replays `create()`
37	  /// verbatim"). A no-op for an unknown [tempId] or one that isn't
38	  /// currently [PendingEntryWriteFailed] (e.g. already in flight, or
39	  /// already resolved).
40	  Future<void> retry(String tempId);
41	
42	  /// Releases the underlying stream resources — wired into `get_it`'s own
43	  /// reset lifecycle (`entries_injection.dart`'s `dispose:`), same
44	  /// convention `SessionExpiryNotifier.dispose()`/`SessionRepository.
45	  /// dispose()` already use.
46	  Future<void> dispose();
47	
48	  /// Every write this tracker currently holds (in flight or failed) —
49	  /// `MeusRegistrosCubit` overlays this on its own confirmed list (Intent).
50	  /// Replay-capable: a late subscriber sees the current snapshot
51	  /// immediately rather than only future changes (`Stream.multi` + cached
52	  /// last value, mirrors `SessionRepositoryImpl.statusStream`,
53	  /// `session_repository_impl.dart:69-89`) — necessary here because
54	  /// `MeusRegistrosCubit` is a long-lived singleton that may subscribe
55	  /// well after a write is already pending (e.g. the user opens "Meus
56	  /// Registros" after already starting a save from Home).
57	  Stream<List<PendingEntryWrite>> get pendingWrites;
58	
59	  /// Broadcasts the real, server-confirmed [Entry] — paired with the
60	  /// [PendingEntryWrite.tempId] it resolved from — the instant a
61	  /// [create]/[retry] call resolves successfully. The one channel
62	  /// `MeusRegistrosCubit` (which never calls [create]/[retry] itself, and
63	  /// never talks to a capture cubit directly, AD-7) has to learn of a
64	  /// just-confirmed write and prepend it into its own state (Boundaries:
65	  /// "tracker drops the record; `MeusRegistrosCubit` prepends the
66	  /// confirmed `Entry` into its own state"). No replay semantics, same
67	  /// rationale `SessionExpiryNotifier.expiredEvents` already documents: a
68	  /// one-shot signal per confirmation, not a value a late subscriber needs
69	  /// to catch up on — a write that confirmed before `MeusRegistrosCubit`
70	  /// ever subscribed will simply arrive through its next `list()`
71	  /// instead.
72	  ///
73	  /// The paired `tempId` (Review finding) lets a listener drop its own
74	  /// locally-held pending placeholder for this exact write in the very
75	  /// same synchronous handler that prepends the confirmed [Entry] —
76	  /// `pendingWrites`' own removal of the same record is a separate
77	  /// `Stream.multi`-wrapped subscription that can otherwise deliver one
78	  /// microtask late, which previously left a one-frame window where both
79	  /// the stale placeholder and the real confirmed entry rendered at once.
80	  Stream<({String tempId, Entry entry})> get confirmedWrites;
81	}
82	
83	/// Default implementation — an in-memory `Map` of outstanding writes
84	/// (Never: "persisting pending writes" — nothing here ever touches disk;
85	/// a killed app loses every pending record, by design, UX-DR30).
86	class PendingEntryWriteTrackerImpl implements PendingEntryWriteTracker {
87	  PendingEntryWriteTrackerImpl({required EntriesRepository repository})
88	    : _repository = repository;
89	
90	  final EntriesRepository _repository;
91	
92	  /// Insertion order matters for display (Boundaries: "Card appears
93	  /// top-of-today... before server responds") — a `Map` preserves it in
94	  /// Dart, and lookups by [PendingEntryWrite.tempId] (for [retry]) stay
95	  /// O(1).
96	  final Map<String, PendingEntryWrite> _pending = {};
97	
98	  final StreamController<List<PendingEntryWrite>> _pendingController =
99	      StreamController<List<PendingEntryWrite>>.broadcast();
100	
101	  final StreamController<({String tempId, Entry entry})> _confirmedController =
102	      StreamController<({String tempId, Entry entry})>.broadcast();
103	
104	  /// Monotonic suffix so two `create()` calls landing in the very same
105	  /// microtask (e.g. two fast capture saves) never collide on
106	  /// [DateTime.now]'s own millisecond resolution.
107	  int _nextSuffix = 0;
108	
109	  List<PendingEntryWrite> get _snapshot => List.unmodifiable(_pending.values);
110	
111	  @override
112	  Stream<List<PendingEntryWrite>> get pendingWrites {
113	    // Mirrors `SessionRepositoryImpl.statusStream` exactly: a fresh
114	    // listener gets the current snapshot synchronously, then every
115	    // further change the shared broadcast controller delivers.
116	    return Stream<List<PendingEntryWrite>>.multi((controller) {
117	      controller.add(_snapshot);
118	      final subscription = _pendingController.stream.listen(
119	        controller.add,
120	        onError: controller.addError,
121	        onDone: controller.close,
122	      );
123	      controller.onCancel = subscription.cancel;
124	    }, isBroadcast: true);
125	  }
126	
127	  @override
128	  Stream<({String tempId, Entry entry})> get confirmedWrites =>
129	      _confirmedController.stream;
130	
131	  void _emitPending() {
132	    if (_pendingController.isClosed) {
133	      return;
134	    }
135	    _pendingController.add(_snapshot);
136	  }
137	
138	  String _generateTempId() =>
139	      'pending-${DateTime.now().microsecondsSinceEpoch}-${_nextSuffix++}';
140	
141	  @override
142	  Future<Either<Failure, Entry>> create({
143	    required String content,
144	    required EntrySource source,
145	    int? mediaDurationSeconds,
146	  }) async {
147	    // Spec amendment (code-review round 1): drops any existing `failed`
148	    // record *before* registering the new `inFlight` one — exactly one
149	    // Insertion Modal exists app-wide, so a user retrying by tapping
150	    // "Salvar" again in the same still-open modal (not via the badge)
151	    // must not leave the superseded attempt's error card as a permanent
152	    // orphan on Meus Registros. Mutated in the same pass as the new
153	    // record's own insertion below, so only one combined snapshot is ever
154	    // emitted for this — never an intermediate "failed just removed, new
155	    // one not yet added" one.
156	    _pending.removeWhere((_, write) => write.status is PendingEntryWriteFailed);
157	    final tempId = _generateTempId();
158	    _pending[tempId] = PendingEntryWrite(
159	      tempId: tempId,
160	      content: content,
161	      source: source,
162	      mediaDurationSeconds: mediaDurationSeconds,
163	      startedAt: DateTime.now(),
164	      status: const PendingEntryWriteInFlight(),
165	    );
166	    _emitPending();
167	
168	    final result = await _repository.create(
169	      content: content,
170	      source: source,
171	      mediaDurationSeconds: mediaDurationSeconds,
172	    );
173	    _resolve(tempId, result);
174	    return result;
175	  }
176	
177	  @override
178	  Future<void> retry(String tempId) async {
179	    final current = _pending[tempId];
180	    if (current == null || current.status is! PendingEntryWriteFailed) {
181	      // Unknown, already in flight, or already resolved.
182	      return;
183	    }
184	    final failedStatus = current.status as PendingEntryWriteFailed;
185	    if (!failedStatus.failure.retryable) {
186	      // Review finding (round 2): the tracker, not just `SyncBadge`'s own
187	      // `onTap` guard, is the authoritative check — a non-retryable
188	      // failure must never be replayed regardless of which caller invokes
189	      // [retry].
190	      return;
191	    }
192	    _pending[tempId] = current.copyWith(
193	      status: const PendingEntryWriteInFlight(),
194	    );
195	    _emitPending();
196	
197	    final result = await _repository.create(
198	      content: current.content,
199	      source: current.source,
200	      mediaDurationSeconds: current.mediaDurationSeconds,
201	    );
202	    _resolve(tempId, result);
203	  }
204	
205	  /// Shared success/failure handling for both [create] and [retry] — on
206	  /// success, drops the pending record and broadcasts the confirmed
207	  /// [Entry]; on failure, flips the record to [PendingEntryWriteFailed]
208	  /// (re-reads [_pending] rather than trusting a closed-over reference, in
209	  /// case a concurrent call already replaced it).
210	  void _resolve(String tempId, Either<Failure, Entry> result) {
211	    result.match(
212	      (failure) {
213	        final latest = _pending[tempId];
214	        if (latest == null) {
215	          return;
216	        }
217	        _pending[tempId] = latest.copyWith(
218	          status: PendingEntryWriteFailed(failure: failure),
219	        );
220	        _emitPending();
221	      },
222	      (entry) {
223	        _pending.remove(tempId);
224	        _emitPending();
225	        if (!_confirmedController.isClosed) {
226	          _confirmedController.add((tempId: tempId, entry: entry));
227	        }
228	      },
229	    );
230	  }
231	
232	  @override
233	  Future<void> dispose() async {
234	    await _pendingController.close();
235	    await _confirmedController.close();
236	  }
237	}
